317	```ts
318	// redact.ts
319	const RULES: [string, RegExp][] = [
320	  ['private_key', /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g],
321	  ['jwt', /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g],
322	  ['bearer', /(Bearer\s+)[A-Za-z0-9._~+/-]{20,}/g],
323	  ['provider_key', /\b(?:sk|pk|rk)-[A-Za-z0-9_-]{16,}/g],
324	  ['github_token', /\bgh[pousr]_[A-Za-z0-9]{20,}/g],
325	  ['aws_key_id', /\bAKIA[0-9A-Z]{16}\b/g],
326	  ['google_key', /\bAIza[0-9A-Za-z_-]{30,}/g],
327	  ['slack_token', /\bxox[baprs]-[A-Za-z0-9-]{10,}/g],
328	  ['assignment', /\b([A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD)[A-Z0-9_]*\s*[=:]\s*["']?)([^\s"'\[]{8,})/g],
329	];
330	export function redact(input: string): { text: string; hits: number } {
331	  let hits = 0; let text = input;
332	  for (const [kind, re] of RULES) {
333	    text = text.replace(re, (...m) => {
334	      hits += 1;
335	      const keep = kind === 'bearer' || kind === 'assignment' ? (m[1] as string) : '';
336	      return `${keep}[REDACTED:${kind}]`;
337	    });
338	  }
339	  return { text, hits };
340	}
341	```
342	The `assignment` rule skips values that already start with `[` so an earlier replacement is not counted twice.
