344	```ts
345	// env.ts
346	import { readFileSync, existsSync } from 'node:fs';
347	import { resolve } from 'node:path';
348	export interface Env {
349	  neatlogsApiKey: string | null; neatlogsEndpoint: string;
350	  gatewayKey: string | null; gatewayBaseUrl: string;
351	  veniceKey: string | null; geminiKeys: string[]; dataDir: string;
352	}
353	export function loadEnv(cwd = process.cwd()): Env {
354	  const file = resolve(cwd, '.env');
355	  if (existsSync(file)) for (const line of readFileSync(file, 'utf8').split('\n')) {
356	    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
357	    if (m && process.env[m[1]!] === undefined) process.env[m[1]!] = m[2]!.replace(/^["']|["']$/g, '');
358	  }
359	  const e = process.env;
360	  return {
361	    neatlogsApiKey: e.NEATLOGS_API_KEY || null,
362	    neatlogsEndpoint: e.NEATLOGS_ENDPOINT || 'https://ingest.neatlogs.com',
363	    gatewayKey: e.LITELLM_API_KEY || null,
364	    gatewayBaseUrl: e.LITELLM_BASE_URL || 'https://litellm.vision.aivar.app/v1',
365	    veniceKey: e.VENICE_API_KEY || null,
366	    geminiKeys: (e.GEMINI_API_KEYS || '').split(',').map((s) => s.trim()).filter(Boolean),
367	    dataDir: resolve(cwd, e.DAILIES_DATA_DIR || '.dailies'),
368	  };
369	}
