383	```ts
384	// facts.ts
385	import type { Session, Facts } from './schema';
386	export function computeFacts(sessions: Session[]): Facts {
387	  const commits = new Set(sessions.flatMap((s) => s.commits));
388	  const files = new Set(sessions.flatMap((s) => s.filesTouched));
389	  const calls = sessions.reduce((n, s) => n + s.entries.filter((e) => e.kind === 'tool_call').length, 0);
390	  const minutes = sessions.reduce((n, s) => n + (s.endedAt ? (Date.parse(s.endedAt) - Date.parse(s.startedAt)) / 60000 : 0), 0);
391	  return {
392	    'sessions.count': sessions.length,
393	    'commits.count': commits.size,
394	    'files.count': files.size,
395	    'turns.total': sessions.reduce((n, s) => n + s.turnCount, 0),
396	    'tools.calls': calls,
397	    'tokens.output': sessions.reduce((n, s) => n + s.tokens.output, 0),
398	    'duration.minutes': Math.round(minutes),
399	  };
400	}
401	```
